// ClientsServiceServer is the server API for ClientsService service.
// All implementations must embed UnimplementedClientsServiceServer
// for forward compatibility.
//
// ClientsService is the domain contract of the core-clients service: the
// client master file (expediente) migrated from the sarionerp monolith.
// The Shell's BFF calls it over gRPC on behalf of the signed-in user
// (shell-core §5.1); the same contract is exposed as REST through the
// grpc-gateway (shell-core §5.3, "dos contratos, no tres mantenimientos").
//
// tenant_id and subject identity are never trusted from the request: the PEP
// interceptor extracts them from the verified access token and the handlers
// read them from the context (core-reference §A.7).
//
// Cross-core surface (consumed by strix-billing when it exists — see
// integrations.md rows G/O/Q): LookupClients, GetClientTaxProfile,
// ValidateClientContact.
type ClientsServiceServer interface {
	// ── Expediente ────────────────────────────────────────────────
	CreateClient(context.Context, *CreateClientRequest) (*Client, error)
	ListClients(context.Context, *ListClientsRequest) (*ListClientsResponse, error)
	GetClient(context.Context, *GetClientRequest) (*Client, error)
	UpdateClient(context.Context, *UpdateClientRequest) (*Client, error)
	DeleteClient(context.Context, *DeleteClientRequest) (*DeleteClientResponse, error)
	// LookupClients resolves a batch of client IDs to their minimal projection
	// {id, name, code, status}. Cross-module name resolution: this replaces the
	// monolith's SQL JOINs against the clients table from billing listings
	// (documents, payments, collections — integrations.md).
	LookupClients(context.Context, *LookupClientsRequest) (*LookupClientsResponse, error)
	// GetClientTaxProfile returns the active custom taxes and the applicable
	// IVA exemption for a client at a given date. This is the surface billing
	// calls on every document total computation (integration G — sync gRPC with
	// short-lived cache on the billing side).
	GetClientTaxProfile(context.Context, *GetClientTaxProfileRequest) (*GetClientTaxProfileResponse, error)
	// ValidateClientContact reports whether a contact belongs to the client
	// within the caller's tenant. Security-relevant FK guard for billing
	// (integration O — blocks cross-tenant contact injection).
	ValidateClientContact(context.Context, *ValidateClientContactRequest) (*ValidateClientContactResponse, error)
	// LookupSuppliers resolves a batch of client IDs to their minimal supplier
	// projection. This is the synchronous lookup a BUYING core (expenses,
	// inventory) makes AT WRITE TIME when it records a purchase against a
	// supplier — it never trusts the request body for issues_receipt, since
	// that flag decides whether the expense's IVA is recoverable. Batch by
	// design: a purchase document line references suppliers, not one supplier
	// at a time. Cap of 1000 ids.
	LookupSuppliers(context.Context, *LookupSuppliersRequest) (*LookupSuppliersResponse, error)
	// ── Importación Excel (preview → confirm) ─────────────────────
	ImportPreview(context.Context, *ImportPreviewRequest) (*ImportPreviewResponse, error)
	ImportConfirm(context.Context, *ImportConfirmRequest) (*ImportConfirmResponse, error)
	// ── Sub-entidades: contactos ──────────────────────────────────
	ListContacts(context.Context, *ListContactsRequest) (*ListContactsResponse, error)
	CreateContact(context.Context, *CreateContactRequest) (*Contact, error)
	UpdateContact(context.Context, *UpdateContactRequest) (*Contact, error)
	DeleteContact(context.Context, *DeleteContactRequest) (*DeleteSubEntityResponse, error)
	// ── Sub-entidades: actividades económicas ─────────────────────
	ListActivities(context.Context, *ListActivitiesRequest) (*ListActivitiesResponse, error)
	CreateActivity(context.Context, *CreateActivityRequest) (*Activity, error)
	UpdateActivity(context.Context, *UpdateActivityRequest) (*Activity, error)
	DeleteActivity(context.Context, *DeleteActivityRequest) (*DeleteSubEntityResponse, error)
	// ── Sub-entidades: exoneraciones de IVA ───────────────────────
	ListExemptions(context.Context, *ListExemptionsRequest) (*ListExemptionsResponse, error)
	CreateExemption(context.Context, *CreateExemptionRequest) (*Exemption, error)
	UpdateExemption(context.Context, *UpdateExemptionRequest) (*Exemption, error)
	DeleteExemption(context.Context, *DeleteExemptionRequest) (*DeleteSubEntityResponse, error)
	// ── Sub-entidades: impuestos personalizados ───────────────────
	ListCustomTaxes(context.Context, *ListCustomTaxesRequest) (*ListCustomTaxesResponse, error)
	CreateCustomTax(context.Context, *CreateCustomTaxRequest) (*CustomTax, error)
	UpdateCustomTax(context.Context, *UpdateCustomTaxRequest) (*CustomTax, error)
	DeleteCustomTax(context.Context, *DeleteCustomTaxRequest) (*DeleteSubEntityResponse, error)
	// ── Sub-entidades: descuentos ─────────────────────────────────
	ListDiscounts(context.Context, *ListDiscountsRequest) (*ListDiscountsResponse, error)
	CreateDiscount(context.Context, *CreateDiscountRequest) (*Discount, error)
	UpdateDiscount(context.Context, *UpdateDiscountRequest) (*Discount, error)
	DeleteDiscount(context.Context, *DeleteDiscountRequest) (*DeleteSubEntityResponse, error)
	// ── Sub-entidades: perfil crediticio (1:1) ────────────────────
	GetCreditProfile(context.Context, *GetCreditProfileRequest) (*CreditProfile, error)
	UpsertCreditProfile(context.Context, *UpsertCreditProfileRequest) (*CreditProfile, error)
	// ── Sub-entidad: perfil de proveedor (1:1) ─────────────────────
	GetSupplierProfile(context.Context, *GetSupplierProfileRequest) (*SupplierProfile, error)
	UpsertSupplierProfile(context.Context, *UpsertSupplierProfileRequest) (*SupplierProfile, error)
	// ── Sub-entidades: documentos adjuntos ────────────────────────
	ListAttachedDocuments(context.Context, *ListAttachedDocumentsRequest) (*ListAttachedDocumentsResponse, error)
	CreateAttachedDocument(context.Context, *CreateAttachedDocumentRequest) (*AttachedDocument, error)
	UpdateAttachedDocument(context.Context, *UpdateAttachedDocumentRequest) (*AttachedDocument, error)
	DeleteAttachedDocument(context.Context, *DeleteAttachedDocumentRequest) (*DeleteSubEntityResponse, error)
	mustEmbedUnimplementedClientsServiceServer()
}

